      "Apresentar ícones de cadeado em mensagens encriptadas",
    publish_keys_wkd_title: "Publicar chaves no WKD",
    publish_keys_wkd_description:
      "Tornar as suas chaves detetáveis através do Web Key Directory",
    publish_to_keyservers_title: "Publicar em servidores de chaves",
    publish_to_keyservers_description:
      "Tornar as suas chaves localizáveis em servidores de chaves públicos",
    info_forward_secrecy_title: "O que é o sigilo futuro?",
    info_forward_secrecy_description:
      "As suas chaves de sessão são renovadas automaticamente de acordo com um calendário. Mesmo que alguém obtivesse hoje a sua chave privada, não conseguiria ler mensagens anteriores, porque cada sessão utilizou uma chave diferente que já não existe.",
    info_key_rotation_interval_title: "Intervalo de rotação de chaves",
    info_key_rotation_interval_description:
      "Com que frequência a sua chave de encriptação é substituída. Quanto mais frequente, mais seguro, mas com um pouco mais de processamento. Uma semana é uma boa predefinição para a maioria das pessoas.",
    info_key_history_limit_title: "Limite do histórico de chaves",
    info_key_history_limit_description:
      "Quantas chaves antigas o Aster guarda para que ainda possa desencriptar e-mails mais antigos. Se o valor for demasiado baixo, as mensagens anteriores à última rotação podem ficar ilegíveis.",
    info_wkd_title: "O que é WKD?",
    info_wkd_description:
      "Uma norma que permite que aplicações de e-mail como Thunderbird ou Proton encontrem automaticamente a sua chave pública. As pessoas podem enviar-lhe correio encriptado sem que tenha de partilhar a sua chave manualmente.",
    info_keyservers_title: "O que são servidores de chaves?",
    info_keyservers_description:
      "Diretórios públicos onde as chaves PGP podem ser pesquisadas por e-mail. Publicar aqui permite que qualquer pessoa encontre a sua chave. Atenção: a maioria dos servidores de chaves não permite remover totalmente uma chave depois de publicada.",
    keyserver_urls_title: "URLs do servidor de chaves",
    keyserver_urls_description:
      "Servidores de chaves adicionais para pesquisar e publicar, além das predefinições (keys.openpgp.org)",
    keyserver_url_placeholder: "https://keys.example.com",
    keyserver_add: "Adicionar",
    keyserver_remove: "Remover",
    keyserver_defaults_label: "Servidores de chaves predefinidos",
    keyserver_custom_label: "Servidores de chaves personalizados",
    keyserver_invalid_url: "Introduza um URL HTTPS válido",
    keyserver_saved: "Lista de servidores de chaves guardada",
    keyserver_publication_status: "Estado da publicação",
    keyserver_status_published: "Publicado",
    keyserver_status_not_published: "Não publicado",
    keyserver_status_awaiting: "A aguardar confirmação",
    keyserver_status_failed: "Falhou",
    keyserver_awaiting_hint:
      "A sua chave foi enviada. Procure na sua caixa de entrada um e-mail de confirmação de keys.openpgp.org e clique no link para concluir a publicação.",
    keyserver_failed_hint:
      "O servidor de chaves rejeitou a sua chave. Tente publicar novamente.",
    keyserver_publish_btn: "Publicar chave",
    keyserver_republish_btn: "Publicar chave novamente",
    keyserver_permanent_warning:
      "Depois de publicadas, as chaves não podem ser totalmente removidas da maioria dos servidores de chaves.",
    keyserver_add_custom_label: "Adicionar servidor de chaves personalizado",
    info_require_encryption_title: "Exigir encriptação",
    info_require_encryption_description:
      "Envie apenas e-mails que possam ser encriptados ponto a ponto. Se um destinatário não tiver uma chave PGP, a mensagem não será enviada. Ative esta opção apenas se nunca enviar e-mails a pessoas fora do PGP.",
    info_storage_format_title: "Sobre o formato de armazenamento",
    info_storage_format_description:
      "O Aster Server guarda os seus e-mails encriptados no armazenamento padrão do Aster. O IPFS privado guarda-os num armazenamento endereçado por conteúdo que também é executado nos servidores do Aster. Em ambos os casos, só as suas chaves os podem desencriptar.",
    info_block_fonts_title: "Porquê bloquear tipos de letra remotos?",
    info_block_fonts_description:
      "Os e-mails podem carregar tipos de letra de servidores externos. Quando são carregados, o servidor do remetente vê o seu IP e fica a saber que abriu a mensagem. É o mesmo truque de um píxel de rastreamento, mas através de tipos de letra.",
    info_block_css_title: "Porquê bloquear folhas de estilo remotas?",
    info_block_css_description:
      "As folhas de estilo nos e-mails funcionam como rastreadores ocultos. Carregar uma indica ao servidor do remetente o seu IP, quando abriu a mensagem e que dispositivo utiliza.",
    info_strip_exif_title: "O que são metadados de imagem?",
    info_strip_exif_description:
      "As fotografias tiradas com telemóveis e câmaras incorporam dados ocultos, como coordenadas GPS, modelo do dispositivo, data e hora e informações da lente. Quando envia uma imagem, estes dados seguem com ela. O Aster remove-os antes do carregamento para que os destinatários vejam apenas os píxeis.",
    info_spy_pixels_title: "O que são píxeis espiões?",
    info_spy_pixels_description:
      "Imagens invisíveis de 1x1 escondidas nos e-mails. Quando são carregadas, o remetente vê o seu IP, quando abriu a mensagem e o tipo do seu dispositivo. O Aster remove-as antes de poderem ser carregadas.",
    info_folder_lock_mode_title: "Modo de bloqueio de pasta",
    info_folder_lock_mode_description:
      "Sessão bloqueia a pasta quando fecha a aplicação ou a sua sessão termina. Ao sair bloqueia-a assim que navega para outro local, pelo que precisa da sua palavra-passe sempre que voltar.",
    info_block_remote_images_title: "Porquê bloquear imagens remotas?",
    info_block_remote_images_description:
      "Quando um e-mail carrega imagens de servidores externos, o remetente pode ver o seu endereço IP e quando o abriu. Bloqueá-las mantém essa informação privada.",
    info_remote_image_loading_title: "Opções de carregamento de imagens",
    info_remote_image_loading_description:
      "Nunca: bloquear sempre as imagens. Perguntar: mostrar um aviso de cada vez. Sempre: carregar sem perguntar. Isto controla quando são feitas exceções à sua definição de bloqueio de imagens.",
    info_tracking_protection_title: "Proteção contra rastreamento",
    info_tracking_protection_description:
      "Impede que os e-mails comuniquem com o exterior quando os abre. Os remetentes utilizam píxeis de rastreamento, tipos de letra e CSS para registar quem abriu os seus e-mails e quando.",
    info_block_tracking_links_title: "O que são links de rastreamento?",
    info_block_tracking_links_description:
      "Os e-mails de marketing acrescentam parâmetros ocultos aos links, como utm_source, fbclid e gclid. Esses parâmetros indicam ao remetente de que campanha veio e confirmam que clicou. O Aster remove-os de todos os links da mensagem, pelo que o link continua a abrir a mesma página sem comunicar nada.",
    info_two_factor_auth_title: "Autenticação de dois fatores",
    info_two_factor_auth_description:
      "Adiciona uma segunda camada de segurança ao início de sessão. Depois da palavra-passe, introduz um código de 6 dígitos da sua aplicação de autenticação.",
    info_session_timeout_title: "Tempo limite da sessão",
    info_session_timeout_description:
      "Termina a sua sessão automaticamente após um período de inatividade. Útil em computadores partilhados ou se pretende proteção quando se afasta.",
